function validate([words]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 5000) return 'words needs 1 to 5000 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length > 300) return 'Each word has at most 300 characters.';
    if (!/^[a-z]*$/.test(word)) return 'Words contain only lowercase English letters.';
  }
  if (new Set(words).size !== words.length) return 'All words must be distinct.';
  return null;
}

