function palindromePairs(words) {
  const indexOf = new Map();
  for (let i = 0; i < words.length; i++) {
    indexOf.set(words[i], i);
  }

  const isPalindrome = (word, left, right) => {
    while (left < right) {
      if (word[left] !== word[right]) {
        return false;
      }
      left++;
      right--;
    }
    return true;
  };

  const result = [];
  for (let i = 0; i < words.length; i++) {
    const word = words[i];
    const reversed = word.split('').reverse().join('');
    for (let k = 0; k <= word.length; k++) {
      if (isPalindrome(word, 0, k - 1)) {
        const j = indexOf.get(reversed.slice(0, word.length - k));
        if (j !== undefined && j !== i) {
          result.push([j, i]);
        }
      }
      if (k < word.length && isPalindrome(word, k, word.length - 1)) {
        const j = indexOf.get(reversed.slice(word.length - k));
        if (j !== undefined && j !== i) {
          result.push([i, j]);
        }
      }
    }
  }
  return result;
}

