function palindromePairs(words) {
  // Try every ordered pair and test the glued string directly.
  const pairs = [];
  for (let i = 0; i < words.length; i++) {
    for (let j = 0; j < words.length; j++) {
      if (i === j) continue;
      const glued = words[i] + words[j];
      if (glued === [...glued].reverse().join('')) pairs.push([i, j]);
    }
  }
  return pairs;
}

