function generate(rand, size) {
  // The seeded rand() repeats after about 10,000 calls, so large inputs draw from a stream seeded by it.
  let state = Math.floor(rand() * 4294967296);
  const stream = () => { state = (state + 0x6D2B79F5) >>> 0; let t = Math.imul(state ^ (state >>> 15), 1 | state); t ^= t + Math.imul(t ^ (t >>> 7), 61 | t); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const next = size === 'large' ? stream : rand;
  const int = (lo, hi) => lo + Math.floor(next() * (hi - lo + 1));
  const reverse = (s) => s.split('').reverse().join('');
  const word = (alphabet, lo, hi) => { let s = ''; const n = int(lo, hi); for (let i = 0; i < n; i++) s += alphabet[int(0, alphabet.length - 1)]; return s; };
  const palindrome = (alphabet, lo, hi) => { const half = word(alphabet, lo, hi); return half + (next() < 0.5 ? '' : alphabet[int(0, alphabet.length - 1)]) + reverse(half); };
  const seen = new Set();
  const words = [];
  const add = (s) => { if (!seen.has(s)) { seen.add(s); words.push(s); } };
  if (size === 'small') {
    const alphabet = next() < 0.7 ? 'ab' : 'abc';
    const n = int(1, 8);
    while (words.length < n) add(word(alphabet, 0, 4));
    return [words];
  }
  const letters = 'abcdefghijklmnopqrstuvwxyz';
  if (next() < 0.7) add('');
  // Plant matching words so the answer is not empty: reverses, and reverses padded with a palindrome.
  for (let t = 0; t < 150; t++) {
    const base = word(letters, 1, 30);
    const pad = palindrome('xyz', 0, 3);
    const kind = int(0, 2);
    if (kind === 0) { add(base); add(reverse(base)); }
    else if (kind === 1) { add(base + pad); add(reverse(base)); }
    else { add(pad + base); add(reverse(base)); }
  }
  for (let t = 0; t < 10; t++) add(word(letters, 250, 300));
  for (let t = 0; t < 100; t++) add(palindrome(letters, 0, 10));
  while (words.length < 2000) add(word(letters, 1, 40));
  for (let i = words.length - 1; i > 0; i--) { const j = int(0, i); [words[i], words[j]] = [words[j], words[i]]; }
  return [words];
}
